                'type' => 'folder',
                'userOwner' => $this->getAdminUser()->getId(),
                'userModification' => $this->getAdminUser()->getId(),
            ]);
            $success = true;
        }
    } else {
        Logger::debug('prevented creating asset because of missing permissions');
    }

    return $this->adminJson(['success' => $success]);
}
