	} else {
		$this->$name = $value;
	}
}
private function get_property( $name ) {
	if ( isset( $this->data[ $name ] ) ) {
		return $this->data[ $name ];
	} else {
		return null;
	}
}
/**
 * Return a list of property dictionaries.
