<?php
namespace WP_SMS;

if (!defined('ABSPATH')) {
    exit;
} // Exit if accessed directly

if (!class_exists('WP_List_Table')) {
    require_once(ABSPATH . 'wp-admin/includes/class-wp-list-table.php');
}
public function __construct()
{
    global $wpdb;

    //Set parent defaults
    parent::__construct(array(
        'singular' => 'ID',     //singular name of the listed records
        'plural'   => 'ID',    //plural name of the listed records
        'ajax'     => false        //does this table support ajax?
    ));

    $this->db        = $wpdb;
    $this->tb_prefix = $wpdb->prefix;
    $this->count     = $this->get_total();
    $this->limit     = $this->get_items_per_page('wp_sms_subscriber_per_page');
    $this->data      = $this->get_data();
    $this->adminUrl  = admin_url('admin.php?page=wp-sms-subscribers');
}
public function column_default($item, $column_name)
{
    switch ($column_name) {
        case 'name':
        case 'mobile':
            return wp_sms_render_quick_reply($item['mobile']);
        case 'activate_key':
            return $item[$column_name];

        case 'group_ID':
            $group = Newsletter::getGroup($item[$column_name]);
            if ($group) {
                return $group->name;
            } else {
                return '-';
            }

        case 'date':
            return sprintf(__('%s <span class="wpsms-time">%s</span>', 'wp-sms'), date_i18n('Y-m-d', strtotime($item[$column_name])), date_i18n('H:i', strtotime($item[$column_name])));

        default:
            return print_r($item, true); //Show the whole array for troubleshooting purposes
    }
}
public function column_name($item)
{
    /**
     * Sanitize the input
     */
    $page = sanitize_text_field($_REQUEST['page']);

    //Build row actions
    $actions = array(
        'edit'   => sprintf('<a href="#" onclick="wp_sms_edit_subscriber(%s)">' . __('Edit', 'wp-sms') . '</a>', $item['ID']),
        'delete' => sprintf('<a href="?page=%s&action=%s&ID=%s">' . __('Delete', 'wp-sms') . '</a>', $page, 'delete', $item['ID']),
    );

    //Return the title contents
    return sprintf('%1$s %3$s',
        /*$1%s*/
        esc_html($item['name']),
        /*$2%s*/
        $item['ID'],
        /*$2%s*/
        $this->row_actions($actions)
    );
}
public function column_status($item)
{
    return Helper::loadTemplate('admin/label-button.php', array(
        'type'  => ($item['status'] == '1' ? 'active' : 'inactive'),
        'label' => ($item['status'] == '1' ? __('Active', 'wp-sms') : __('Inactive', 'wp-sms'))
    ));
}
/**
 * Usort Function
 *
 * @param $a
 * @param $b
 *
 * @return array
 */
public function usort_reorder($a, $b)
{
    $orderby = (!empty($_REQUEST['orderby'])) ? sanitize_text_field($_REQUEST['orderby']) : 'date'; //If no sort, default to sender
    $order   = (!empty($_REQUEST['order'])) ? sanitize_text_field($_REQUEST['order']) : 'desc'; //If no order, default to asc
    $result  = strcmp($a[$orderby], $b[$orderby]); //Determine sort order

    return ($order === 'asc') ? $result : -$result; //Send final sort direction to usort
}
public function mobile_or_country_query($where)
{
    if (isset($_GET['group_id']) && $_GET['group_id']) {
        $group_id = sanitize_text_field($_GET['group_id']);
        $where = "WHERE group_ID = {$group_id}";
    }

    if (isset($_GET['country_code']) && $_GET['country_code']) {
        $country_code = sanitize_text_field($_GET['country_code']);
        if ($where) {
            $where .= " AND mobile LIKE '{$country_code}%'";
        } else {
            $where = "WHERE mobile LIKE '{$country_code}%'";
        }
    }
    return $where;
}
public function column_custom_fields($item)
{
    $customFields = unserialize($item['custom_fields']);

    if (is_array($customFields)) {
        foreach ($customFields as $key => $value) {
            printf('<div class="wpsms-custom-field"><strong>%s</strong>: %s</div>', $key, $value);
        }
    }
}
public function column_cb($item)
{
    return sprintf(
        '<input type="checkbox" name="%1$s[]" value="%2$s" />',
        /*$1%s*/
        $this->_args['singular'],  //Let's simply repurpose the table's singular label ("movie")
        /*$2%s*/
        $item['ID']                //The value of the checkbox should be the record's id
    );
}
public function prepare_items()
{
    /**
     * First, lets decide how many records per page to show
     */
    $per_page = $this->limit;

    /**
     * REQUIRED. Now we need to define our column headers. This includes a complete
     * array of columns to be displayed (slugs & titles), a list of columns
     * to keep hidden, and a list of columns that are sortable. Each of these
     * can be defined in another method (as we've done here) before being
     * used to build the value for our _column_headers property.
     */
    $columns  = $this->get_columns();
    $hidden   = array();
    $sortable = $this->get_sortable_columns();

    /**
     * REQUIRED. Finally, we build an array to be used by the class for column
     * headers. The $this->_column_headers property takes an array which contains
     * 3 other arrays. One for all columns, one for hidden columns, and one
     * for sortable columns.
     */
    $this->_column_headers = array($columns, $hidden, $sortable);

    /**
     * Optional. You can handle your bulk actions however you see fit. In this
     * case, we'll handle them within our package just to keep things clean.
     */
    $this->process_bulk_action();

    /**
     * Instead of querying a database, we're going to fetch the example data
     * property we created for use in this plugin. This makes this example
     * package slightly different than one you might build on your own. In
     * this example, we'll be using array manipulation to sort and paginate
     * our data. In a real-world implementation, you will probably want to
     * use sort and pagination data to build a custom query instead, as you'll
     * be able to use your precisely-queried data immediately.
     */
    $data = $this->data;

    /**
     * This checks for sorting input and sorts the data in our array accordingly.
     *
     * In a real-world situation involving a database, you would probably want
     * to handle sorting by passing the 'orderby' and 'order' values directly
     * to a custom query. The returned data will be pre-sorted, and this array
     * sorting technique would be unnecessary.
     */
    usort($data, '\WP_SMS\Subscribers_List_Table::usort_reorder');

    /**
     * REQUIRED for pagination. Let's check how many items are in our data array.
     * In real-world use, this would be the total number of items in your database,
     * without filtering. We'll need this later, so you should always include it
     * in your own package classes.
     */
    $total_items = $this->count;

    /**
     * REQUIRED. Now we can add our *sorted* data to the items property, where
     * it can be used by the rest of the class.
     */
    $this->items = $data;

    /**
     * REQUIRED. We also have to register our pagination options & calculations.
     */
    $this->set_pagination_args(array(
        'total_items' => $total_items,                  //WE have to calculate the total number of items
        'per_page'    => $per_page,                     //WE have to determine how many items to show on a page
        'total_pages' => ceil($total_items / $per_page)   //WE have to calculate the total number of pages
    ));
}
/**
 * @param $which
 * @return void
 */
protected function extra_tablenav($which)
{
    switch ($which) {
        case 'top':

            // Filter by Group
            echo Helper::loadTemplate('admin/group-filter.php', array(
                'groups'   => Newsletter::getGroups(),
                'selected' => (isset($_GET['group_id']) ? $_GET['group_id'] : '')
            ));

            // Filter by Country
            echo Helper::loadTemplate('admin/country-filter.php', array(
                'countries' => Newsletter::filterSubscribersByCountry(),
                'selected'  => (isset($_GET['country_code']) ? $_GET['country_code'] : '')
            ));

            break;
    }
}

