function sanitize($data) {
    global $fmdb;

    if (is_string($data)) {
        if ($fmdb->use_mysqli) {
            return @mysqli_real_escape_string($fmdb->dbh, $data);
        } else {
            return @mysql_real_escape_string($data);
        }
    }
    return $data;
}
/**
 * Counts the number of dimensions in an array
 *
 * @since 2.0
 * @package facileManager
 *
 * @param array $array Array to count
 * @return int Number of dimensions
 */
function countArrayDimensions($array) {
	if (is_array($array)) {
		if (is_array(@reset($array))) {
			$count = countArrayDimensions(reset($array)) + 1;
		} else {
			$count = 1;
		}
	} else {
		$count = 1;
	}

	return $count;
}
/**
 * Use MySQLi or not
 *
 * @since 3.0
 * @package facileManager
 *
 * @return boolean
 */
function useMySQLi() {
	include(ABSPATH . 'fm-includes/version.php');

	if (function_exists('mysqli_connect')) {
		if (version_compare(phpversion(), '5.5', '>=') || ! function_exists('mysql_connect')) {
			return true;
		} elseif (strpos($fm_version, '-') !== false) {
			return true;
		}
	}

	return false;
}

