    mutationKey?: MutationKey
    state: MutationState
    meta?: MutationMeta
    scope?: MutationScope
  }
interface DehydratedQuery {
    queryHash: string
    queryKey: QueryKey
    state: QueryState
    meta?: QueryMeta
  }
