    $store = \GO\Base\Data\Store::newInstance(\GO\Files\Model\File::model());
    $store->getColumnModel()->formatColumn('path', '$model->path', array(), array('first_name', 'last_name'));

//		$findParams = $store->getDefaultParams($params);

