                ->addRawCondition('`t`.`id`', '`sc`.`entityId`')
                ->addCondition('entityTypeId', \GO\Files\Model\File::model()->modelTypeId(),'=','sc');

    $findParams->join(\GO\Base\Model\SearchCacheRecord::model()->tableName(), $joinSearchCacheCriteria, 'sc', 'INNER');


