                'name'=>$fileHandler->getName(),
                'handler'=>$fileHandler->getHandler($file),
                'iconCls'=>$fileHandler->getIconCls(),
                'cls'=>  get_class($fileHandler),
                'extension'=>$file->extension
        ));	
    }	

    return $store->getData();		
}
