func saveSchema(out *tar.Writer, c *chart.Chart, base string) error {
	if c.Schema != nil {
		if !json.Valid(c.Schema) {
			return errors.New("Invalid JSON in " + SchemafileName)
		}
		return writeToTar(out, filepath.Join(base, SchemafileName), c.Schema)
	}
	return nil
}
