private static final Logger LOGGER = LogManager.getLogger(FileReadingIterator.class);
    @VisibleForTesting
    static final int MAX_SOCKET_TIMEOUT_RETRIES = 5;

    private static final Predicate<URI> MATCH_ALL_PREDICATE = (URI input) -> true;

