        private long lineNumber;
        private String line;
        private IOException failure;

        public LineCursor() {
        }

        public LineCursor(URI uri, long lineNumber, @Nullable String line, @Nullable IOException failure) {
            this.uri = uri;
            this.lineNumber = lineNumber;
            this.line = line;
