    $loader = \Pimcore::getContainer()->get('pimcore.implementation_loader.asset.metadata.data');

    return $this->render(
        '@PimcoreAdmin/admin/asset/show_version_' . strtolower($asset->getType()) . '.html.twig',
        [
            'asset' => $asset,
            'version' => $version,
            'loader' => $loader,
        ]
    );
}
