 */
private function set_defaults() {

	$defaults = $this->default_values();

	if ( ! is_array( $defaults ) || empty( $defaults ) )
		return;

	foreach ( $defaults as $property => $value ) {
		if ( $this->$property === null )
			$this->$property = $value;
	}

}
