public static function build() {
	global $wpdb;

	$property_sql = array();
	foreach ( static::properties() as $property )
		$property_sql[] = "`{$property['name']}` {$property['type']}";

	$sql = 'CREATE TABLE IF NOT EXISTS '
			. static::table_name()
			. ' ('
			. implode( ',', $property_sql )
			. ' ) CHARACTER SET utf8;'
