 * @return (bool) query success
 */
public function update_attribute($attribute, $value) {
	global $wpdb;

	$this->$attribute = $value;

	$sql = sprintf(
		"UPDATE %s SET %s = '%s' WHERE id = %s",
		static::table_name(),
		$attribute,
		mysqli_real_escape_string($value),
		$this->id
	);

	return $wpdb->query( $sql );
