    if ( ! $button = \PodloveSubscribeButton\Model\Button::get_button_by_name($args['button']) )
        return sprintf( __('Oops. There is no button with the ID "%s".', 'podlove-subscribe-button'), $args['button'] );

    // Get button styling and options
