	global $wpdb;

	$class = get_called_class();
	$models = array();

	$rows = $wpdb->get_results(
		'SELECT * FROM ' . static::table_name() . ' WHERE ' . $where
	);

	if ( ! $rows ) {
		return array();
	}

	foreach ( $rows as $row ) {
		$model = new $class();
		$model->flag_as_not_new();
		foreach ( $row as $property => $value ) {
			$model->$property = static::unserialize_property($value);
		}
		$models[] = $model;
	}

	return $models;
}
