                    )
            );

            if ($formFields) {
                $forminator_forms['forminator_notify_enable_field_form_' . $form->id]   = array(
                    'id'      => 'forminator_notify_enable_field_form_' . $form->id,
                    'name'    => __('Send SMS to field', 'wp-sms'),
