private static function interpret_width_attribute( $width_attribute = null ) {
    if ( $width_attribute == 'auto' )
        return 'on';
    if ( $width_attribute && $width_attribute !== 'auto' )
        return 'off';

    return get_option('podlove_subscribe_button_default_autowidth', 'on');
}

