private function printVariables($variables)
{
    $result = "";
    foreach ($variables as $key => $value) {
        preg_match("/(%field-|%)(.+)*\%/", $key, $match);
        $label  = $match[1] ? $match[2] : "";
        $result .= esc_html($label) . ": <code>" . esc_html($key) . "</code> ";
    }
    return $result;
}
