	"github.com/gin-gonic/gin"
	"gorm.io/gorm/clause"
	"net/http"
)

func (c *Ctx[T]) Create() {

	errs := c.validate()

	if len(errs) > 0 {
		c.ctx.JSON(http.StatusNotAcceptable, gin.H{
			"message": "Requested with wrong parameters",
			"errors":  errs,
		})
		return
	}

	db := model.UseDB()

	c.beforeDecodeHook()

	if c.abort {
		return
	}

	err := map2struct.WeakDecode(c.Payload, &c.Model)

	if err != nil {
		errHandler(c.ctx, err)
		return
	}

	c.beforeExecuteHook()

	if c.abort {
		return
	}

	// skip all associations
	err = db.Omit(clause.Associations).Create(&c.Model).Error

	if err != nil {
		errHandler(c.ctx, err)
		return
	}

	tx := db.Preload(clause.Associations)
	for _, v := range c.preloads {
		tx = tx.Preload(v)
	}
	tx.First(&c.Model)

	if len(c.executedHookFunc) > 0 {
		for _, v := range c.executedHookFunc {
			v(c)

			if c.abort {
				return
			}
		}
	}
	if c.nextHandler != nil {
		(*c.nextHandler)(c.ctx)
	} else {
		c.ctx.JSON(http.StatusOK, c.Model)
	}
}

