	if err != nil {
		errHandler(c.ctx, err)
		return
	}

	c.beforeExecuteHook()
	if c.abort {
		return
	}

	err = db.Model(&dbModel).Select(selectedFields).Updates(&c.Model).Error

	if err != nil {
		c.AbortWithError(err)
		return
	}

	if len(c.executedHookFunc) > 0 {
		for _, v := range c.executedHookFunc {
			v(c)

			if c.abort {
				return
			}
		}
	}

	if c.nextHandler != nil {
		(*c.nextHandler)(c.ctx)
	} else {
