func (c *Ctx[T]) validate() (errs gin.H) {
	c.Payload = make(gin.H)

	_ = c.ctx.ShouldBindJSON(&c.Payload)

	errs = validate.ValidateMap(c.Payload, c.rules)

	if len(errs) > 0 {
