func (c *Ctx[T]) Recover() {
	if c.abort {
		return
	}
	id := c.ctx.Param("id")

	c.beforeExecuteHook()

	db := model.UseDB()
	var dbModel T

	result := db.Unscoped()
	if len(c.gormScopes) > 0 {
		result = result.Scopes(c.gormScopes...)
