}

func (c *Ctx[T]) Destroy() {
	if c.abort {
		return
	}
	id := c.ctx.Param("id")

	c.beforeExecuteHook()

	db := model.UseDB()
	var dbModel T

	result := db
	if len(c.gormScopes) > 0 {
