 */
function parseAjaxOutput($output) {
	global $fmdb;

	$message_array['content'] = $output;
	if ($message_array['content'] !== true) {
		if (strpos($message_array['content'], "\n") !== false || isset($fmdb->last_error)) {
			unset($_POST);
