	$module_toolbar = $fm_new_version_available = $account_menu = $user_account_menu = $module_menu = $module_version_info = null;

	if ($help != 'help-file') {
		$auth_method = getOption('auth_method');
		if ($auth_method) {
			if ($_SESSION['user']['account_id'] != 1) {
				$account = getNameFromID($_SESSION['user']['account_id'], 'fm_accounts', 'account_', 'account_id', 'account_name');
				$account_menu = <<<HTML
