		</div>
$module_menu
$module_toolbar_right
$search
$process_all
	</div>
	<div id="help">
		<div id="help_topbar">
			<p class="title">fmHelp</p>
			<p id="help_buttons">{$__FM_CONFIG['icons']['popout']} {$__FM_CONFIG['icons']['close']}</p>
		</div>
		<div id="help_file_container">
		$help_file
		</div>
