<?php
/**
 * Throws HTTP Error
 *
 * @since 1.0
 * @package facileManager
 */
function throwHTTPError($code = '404') {
	$status_codes = array('404' => 'Not Found');

	header( "HTTP/1.0 $code " . $status_codes[$code] );
