function printMenu() {
	global $__FM_CONFIG, $menu, $submenu;

	$main_menu_html = null;

	list($filtered_menu, $filtered_submenu) = getCurrentUserMenu();
	ksort($filtered_menu);
	ksort($filtered_submenu);

	$i = 1;
	foreach ($filtered_menu as $position => $main_menu_array) {
