		$secondary_fields = implode(" $direction,", $id);
		$secondary_fields = ' ' . sanitize(substr($secondary_fields, strlen($primary_field)));
	} else {
		$primary_field = sanitize($id);
		$secondary_fields = null;
	}

	if ($ip_sort) {
