function basicDelete($table, $id, $field = 'id', $include_account_id = true) {
	global $fmdb;

	$account_id = $include_account_id ? "account_id='{$_SESSION['user']['account_id']}' AND" : null;

	$query = "DELETE FROM `$table` WHERE $account_id `$field`='" . sanitize($id) . "'";

