function serializeAndGenerateHTML(stream, transformer, idJSON, count) {
    const serializedCacheArgs = stream
      .map((entry) => transformer.serialize(entry))
      .map((entry) => JSON.stringify(entry))
      .join(',');

    const html = [
      `window[${idJSON}] = window[${idJSON}] || [];`,
      `window[${idJSON}].push(${serializedCacheArgs});`,
    ];

    return (
      <script
        key={count.current++}
        dangerouslySetInnerHTML={{
          __html: html.join(''),
        }}
      />
    );
  }

const serializedSymbol = Symbol('serialized')
interface DataTransformer {
  serialize(object: any): any
  deserialize(object: any): any
}
interface TypedDataTransformer<TData> {
  serialize: (obj: TData) => Serialized<TData>
  deserialize: (obj: Serialized<TData>) => TData
}
interface HydrationStreamContext<TShape> {
  id: string
  stream: {
    /**
     * **Server method**
     * Push a new entry to the stream
     * Will be ignored on the client
     */
    push: (...shape: Array<TShape>) => void
  }
}
export interface HydrationStreamProviderProps<TShape> {
  children: React.ReactNode
  /**
   * Optional transformer to serialize/deserialize the data
   * Example devalue, superjson et al
   */
  transformer?: DataTransformer
  /**
   * **Client method**
   * Called in the browser when new entries are received
   */
  onEntries: (entries: Array<TShape>) => void
  /**
   * **Server method**
   * onFlush is called on the server when the cache is flushed
   */
  onFlush?: () => Array<TShape>
}
export function createHydrationStreamProvider<TShape>() {
  const context = React.createContext<HydrationStreamContext<TShape>>(
    null as any,
  )
  /**

   * 1. (Happens on server): `useServerInsertedHTML()` is called **on the server** whenever a `Suspense`-boundary completes
   *    - This means that we might have some new entries in the cache that needs to be flushed
   *    - We pass these to the client by inserting a `<script>`-tag where we do `window[id].push(serializedVersionOfCache)`
   * 2. (Happens in browser) In `useEffect()`:
   *   - We check if `window[id]` is set to an array and call `push()` on all the entries which will call `onEntries()` with the new entries
   *   - We replace `window[id]` with a `push()`-method that will be called whenever new entries are received
   **/
  function UseClientHydrationStreamProvider(props: {
    children: React.ReactNode
    /**
     * Optional transformer to serialize/deserialize the data
     * Example devalue, superjson et al
     */
    transformer?: DataTransformer
    /**
     * **Client method**
     * Called in the browser when new entries are received
     */
    onEntries: (entries: Array<TShape>) => void
    /**
     * **Server method**
     * onFlush is called on the server when the cache is flushed
     */
    onFlush?: () => Array<TShape>
  }) {
    // unique id for the cache provider
    const id = `__RQ${React.useId()}`
    const idJSON = htmlEscapeJsonString(JSON.stringify(id))
const [transformer] = React.useState(
      () =>
        (props.transformer ?? {
          // noop
          serialize: (obj: any) => obj,
          deserialize: (obj: any) => obj,
        }) as unknown as TypedDataTransformer<TShape>,
    )
// <server stuff>
    const [stream] = React.useState<Array<TShape>>(() => {
      if (typeof window !== 'undefined') {
        return {
          push() {
            // no-op on the client
          },
        } as unknown as Array<TShape>
      }
      return []
    })
    const count = React.useRef(0)
// <client stuff>
    const onEntriesRef = React.useRef(props.onEntries)
    React.useEffect(() => {
      onEntriesRef.current = props.onEntries
    })

    React.useEffect(() => {
      // Client: consume cache:
      const onEntries = (...serializedEntries: Array<Serialized<TShape>>) => {
        const entries = serializedEntries.map((serialized) =>
          transformer.deserialize(serialized),
        )
        onEntriesRef.current(entries)
      }

      const win = window as any
      // Register cache consumer
      const winStream: Array<Serialized<TShape>> = win[id] ?? []

      onEntries(...winStream)

      // Register our own consumer
      win[id] = {
        push: onEntries,
      }

      return () => {
        // Cleanup after unmount
        win[id] = []
      }
    }, [id, transformer])
    // </client stuff>
return (
      <context.Provider value={{ stream, id }}>
        {props.children}
      </context.Provider>
    )
  }
return {
    Provider: UseClientHydrationStreamProvider,
    context,
  }
}
function useServerInsertedHTML(props, stream, transformer, idJSON, count) {
  // This only happens on the server
  stream.push(...(props.onFlush?.() ?? []));

  if (!stream.length) {
    return null;
  }

  // Call the function to serialize and generate HTML
  return serializeAndGenerateHTML(stream, transformer, idJSON, count);
}
type Listener = (focused: boolean) => void

type SetupFn = (
  setFocused: (focused?: boolean) => void,
) => (() => void) | undefined

export class FocusManager extends Subscribable<Listener> {
  #focused?: boolean
  #cleanup?: () => void

  #setup: SetupFn

  constructor() {
    super()
    this.#setup = (onFocus) => {
      // addEventListener does not exist in React Native, but window does
      // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
      if (!isServer && window.addEventListener) {
        const listener = () => onFocus()
        // Listen to visibilitychange
        window.addEventListener('visibilitychange', listener, false)

        return () => {
          // Be sure to unsubscribe if a new handler is set
          window.removeEventListener('visibilitychange', listener)
        }
      }
      return
    }
  }

  protected onSubscribe(): void {
    if (!this.#cleanup) {
      this.setEventListener(this.#setup)
    }
  }

  protected onUnsubscribe() {
    if (!this.hasListeners()) {
      this.#cleanup?.()
      this.#cleanup = undefined
    }
  }

  setEventListener(setup: SetupFn): void {
    this.#setup = setup
    this.#cleanup?.()
    this.#cleanup = setup((focused) => {
      if (typeof focused === 'boolean') {
        this.setFocused(focused)
      } else {
        this.onFocus()
      }
    })
  }

  setFocused(focused?: boolean): void {
    const changed = this.#focused !== focused
    if (changed) {
      this.#focused = focused
      this.onFocus()
    }
  }

  onFocus(): void {
    const isFocused = this.isFocused()
    this.listeners.forEach((listener) => {
      listener(isFocused)
    })
  }

  isFocused(): boolean {
    if (typeof this.#focused === 'boolean') {
      return this.#focused
    }

    // document global can be unavailable in react native
    // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
    return globalThis.document?.visibilityState !== 'hidden'
  }
}

export const focusManager = new FocusManager()
import type {
    DefaultError,
    MutationKey,
    MutationMeta,
    MutationOptions,
    MutationScope,
    QueryKey,
    QueryMeta,
    QueryOptions,
  } from './types'
  import type { QueryClient } from './queryClient'
  import type { Query, QueryState } from './query'
  import type { Mutation, MutationState } from './mutation'

  // TYPES
export interface DehydrateOptions {
    shouldDehydrateMutation?: (mutation: Mutation) => boolean
    shouldDehydrateQuery?: (query: Query) => boolean
  }
export interface HydrateOptions {
    defaultOptions?: {
      queries?: QueryOptions
      mutations?: MutationOptions<unknown, DefaultError, unknown, unknown>
    }
  }
interface DehydratedMutation {
    mutationKey?: MutationKey
    state: MutationState
    meta?: MutationMeta
    scope?: MutationScope
  }
interface DehydratedQuery {
    queryHash: string
    queryKey: QueryKey
    state: QueryState
    meta?: QueryMeta
  }
export interface DehydratedState {
    mutations: Array<DehydratedMutation>
    queries: Array<DehydratedQuery>
  }
function dehydrateMutation(mutation: Mutation): DehydratedMutation {
    return {
      mutationKey: mutation.options.mutationKey,
      state: mutation.state,
      ...(mutation.options.scope && { scope: mutation.options.scope }),
      ...(mutation.meta && { meta: mutation.meta }),
    }
  }
// Most config is not dehydrated but instead meant to configure again when
  // consuming the de/rehydrated data, typically with useQuery on the client.
  // Sometimes it might make sense to prefetch data on the server and include
  // in the html-payload, but not consume it on the initial render.
  function dehydrateQuery(query: Query): DehydratedQuery {
    return {
      state: query.state,
      queryKey: query.queryKey,
      queryHash: query.queryHash,
      ...(query.meta && { meta: query.meta }),
    }
  }
export function defaultShouldDehydrateMutation(mutation: Mutation) {
    return mutation.state.isPaused
  }
export function defaultShouldDehydrateQuery(query: Query) {
    return query.state.status === 'success'
  }
export function dehydrate(
    client: QueryClient,
    options: DehydrateOptions = {},
  ): DehydratedState {
    const filterMutation =
      options.shouldDehydrateMutation ?? defaultShouldDehydrateMutation

    const mutations = client
      .getMutationCache()
      .getAll()
      .flatMap((mutation) =>
        filterMutation(mutation) ? [dehydrateMutation(mutation)] : [],
      )

    const filterQuery =
      options.shouldDehydrateQuery ?? defaultShouldDehydrateQuery

    const queries = client
      .getQueryCache()
      .getAll()
      .flatMap((query) => (filterQuery(query) ? [dehydrateQuery(query)] : []))

    return { mutations, queries }
  }
export function hydrate(
    client: QueryClient,
    dehydratedState: unknown,
    options?: HydrateOptions,
  ): void {
    if (typeof dehydratedState !== 'object' || dehydratedState === null) {
      return
    }
    const mutationCache = client.getMutationCache()
    const queryCache = client.getQueryCache()

    // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
    const mutations = (dehydratedState as DehydratedState).mutations || []
    // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
    const queries = (dehydratedState as DehydratedState).queries || []

    mutations.forEach(({ state, ...mutationOptions }) => {
      mutationCache.build(
        client,
        {
          ...options?.defaultOptions?.mutations,
          ...mutationOptions,
        },
        state,
      )
    })

    queries.forEach(({ queryKey, state, queryHash, meta }) => {
      const query = queryCache.get(queryHash)

      // Do not hydrate if an existing query exists with newer data
      if (query) {
        if (query.state.dataUpdatedAt < state.dataUpdatedAt) {
          // omit fetchStatus from dehydrated state
          // so that query stays in its current fetchStatus
          const { fetchStatus: _ignored, ...dehydratedQueryState } = state
          query.setState(dehydratedQueryState)
        }
        return
      }

      // Restore query
      queryCache.build(
        client,
        {
          ...options?.defaultOptions?.queries,
          queryKey,
          queryHash,
          meta,
        },
        // Reset fetch status to idle to avoid
        // query being stuck in fetching state upon hydration
        {
          ...state,
          fetchStatus: 'idle',
        },
      )
    })
  }
import { notifyManager } from './notifyManager'
import { Removable } from './removable'
import { createRetryer } from './retryer'
import type {
  DefaultError,
  MutationMeta,
  MutationOptions,
  MutationStatus,
} from './types'
import type { MutationCache } from './mutationCache'
import type { MutationObserver } from './mutationObserver'
import type { Retryer } from './retryer'
// TYPES

interface MutationConfig<TData, TError, TVariables, TContext> {
  mutationId: number
  mutationCache: MutationCache
  options: MutationOptions<TData, TError, TVariables, TContext>
  state?: MutationState<TData, TError, TVariables, TContext>
}
export interface MutationState<
  TData = unknown,
  TError = DefaultError,
  TVariables = unknown,
  TContext = unknown,
> {
  context: TContext | undefined
  data: TData | undefined
  error: TError | null
  failureCount: number
  failureReason: TError | null
  isPaused: boolean
  status: MutationStatus
  variables: TVariables | undefined
  submittedAt: number
}
interface FailedAction<TError> {
  type: 'failed'
  failureCount: number
  error: TError | null
}
interface PendingAction<TVariables, TContext> {
  type: 'pending'
  isPaused: boolean
  variables?: TVariables
  context?: TContext
}
interface ErrorAction<TError> {
  type: 'error'
  error: TError
}

interface PauseAction {
  type: 'pause'
}

interface ContinueAction {
  type: 'continue'
}
export type Action<TData, TError, TVariables, TContext> =
  | ContinueAction
  | ErrorAction<TError>
  | FailedAction<TError>
  | PendingAction<TVariables, TContext>
  | PauseAction
  | SuccessAction<TData>

// CLASS
export class Mutation<
  TData = unknown,
  TError = DefaultError,
  TVariables = unknown,
  TContext = unknown,
> extends Removable {
  state: MutationState<TData, TError, TVariables, TContext>
  options!: MutationOptions<TData, TError, TVariables, TContext>
  readonly mutationId: number

  #observers: Array<MutationObserver<TData, TError, TVariables, TContext>>
  #mutationCache: MutationCache
  #retryer?: Retryer<TData>

  constructor(config: MutationConfig<TData, TError, TVariables, TContext>) {
    super()

    this.mutationId = config.mutationId
    this.#mutationCache = config.mutationCache
    this.#observers = []
    this.state = config.state || getDefaultState()

    this.setOptions(config.options)
    this.scheduleGc()
  }

  setOptions(
    options: MutationOptions<TData, TError, TVariables, TContext>,
  ): void {
    this.options = options

    this.updateGcTime(this.options.gcTime)
  }

  get meta(): MutationMeta | undefined {
    return this.options.meta
  }

  addObserver(observer: MutationObserver<any, any, any, any>): void {
    if (!this.#observers.includes(observer)) {
      this.#observers.push(observer)

      // Stop the mutation from being garbage collected
      this.clearGcTimeout()

      this.#mutationCache.notify({
        type: 'observerAdded',
        mutation: this,
        observer,
      })
    }
  }

          }
        case 'continue':
          return {
            ...state,
            isPaused: false,
          }
        case 'pending':
          return {
            ...state,
            context: action.context,
            data: undefined,
            failureCount: 0,
            failureReason: null,
            error: null,
            isPaused: action.isPaused,
            status: 'pending',
            variables: action.variables,
            submittedAt: Date.now(),
          }
        case 'success':
          return {
            ...state,
            data: action.data,
            failureCount: 0,
            failureReason: null,
            error: null,
            status: 'success',
            isPaused: false,
          }
        case 'error':
          return {
            ...state,
            data: undefined,
            error: action.error,
            failureCount: state.failureCount + 1,
            failureReason: action.error,
            isPaused: false,
            status: 'error',
          }
      }
    }
    this.state = reducer(this.state)

    notifyManager.batch(() => {
      this.#observers.forEach((observer) => {
        observer.onMutationUpdate(action)
      })
      this.#mutationCache.notify({
        mutation: this,
        type: 'updated',
        action,
      })
    })
  }
}
export function getDefaultState<
  TData,
  TError,
  TVariables,
  TContext,
>(): MutationState<TData, TError, TVariables, TContext> {
  return {
    context: undefined,
    data: undefined,
    error: null,
    failureCount: 0,
    failureReason: null,
    isPaused: false,
    status: 'idle',
    variables: undefined,
    submittedAt: 0,
  }
}

