export async function getHeadingId(
  parser: IMarkdownParser,
  raw: string,
  level: number
) {
  const innerHTML = await parser.render(raw);

  if (!innerHTML) {
    return null;
  }

  const container = document.createElement('div');
  container.innerHTML = innerHTML;
