        </TableOfContentsItem>
    );
    return [currentTree, nextCandidateIndex];
    };

    const trees = new Array<JSX.Element>();
    let currentIndex = 0;
    while (currentIndex < this.props.headings.length) {
    const [tree, nextIndex] = buildOneTree(currentIndex);
    trees.push(tree);
    currentIndex = nextIndex;
    }

    return trees;
}
