    /**
     * Type of document supported by the model.
     */
    documentType: string;
    /**
     * List of headings to render.
     */
    headings: TableOfContents.IHeading[];
    /**
     * Set active heading.
     */
    setActiveHeading: (heading: TableOfContents.IHeading) => void;
