) {
  const innerHTML = await parser.render(raw);

  if (!innerHTML) {
    return null;
  }

  const container = document.createElement('div');
  container.innerHTML = innerHTML;
  const header = container.querySelector(`h${level}`);
  if (!header) {
    return null;
  }

  return renderMarkdown.createHeaderId(header);
}
