    /*
    * @private
    */
    function onConnect() {
        let widget = app.shell.currentWidget;
        if (!widget) {
        return;
        }
        let model = tracker.get(widget);
        if (!model) {
        model = tocRegistry.getModel(widget, configuration) ?? null;
        if (model) {
            tracker.add(widget, model);
