protected function actionDownload($params) {

    \GO::session()->closeWriting();

    \GO::setMaxExecutionTime(0);

    try {
        if (isset($params['path'])) {
            $folder = \GO\Files\Model\Folder::model()->findByPath(dirname($params['path']));
            if (!$folder) {
                throw new NotFound($params['path']);
            }
            $file = $folder->hasFile(\GO\Base\Fs\File::utf8Basename($params['path']));
        } else {
            $file = \GO\Files\Model\File::model()->findByPk($params['id'], false, true);
        }

        if (!$file)
            throw new \GO\Base\Exception\NotFound();

        if (!empty($params['random_code'])) {
            if ($file->random_code != $params['random_code'])
                throw new \GO\Base\Exception\NotFound();

            if (time() > $file->expire_time)
                throw new \Exception(\GO::t("Sorry, the download link for this file has expired", "files"));
        } else {
            $public = substr($file->path, 0, 6) == 'public';

            if (!$public) {
                if (!\GO::user() || !$file->checkPermissionLevel(\GO\Base\Model\Acl::READ_PERMISSION)) {
                    throw new \GO\Base\Exception\AccessDenied();
                }
            }
        }

        $ua_info = \donatj\UserAgent\parse_user_agent();
        if($ua_info['browser'] == 'Safari' && $file->extension == 'webm' && !strstr(Request::get()->getUri(), 'webm')) {
            //workaround webm bug in safari that needs a webm extension :(
            header("Location: " . str_replace('index.php?', 'index.php/' . rawurlencode($file->name) . '?', Request::get()->getFullUrl()));
            exit();
        }


        // Show the file inside the browser or give it as a download
        $inline = true; // Defaults to show inside the browser
        if (isset($params['inline']) && ((bool)$params['inline'] === false || $params['inline'] == 'false')) {
            $inline = false;
        }

//			\GO\Base\Util\Http::outputDownloadHeaders($file->fsFile, $inline, !empty($params['cache']));
        $file->open();

        $this->fireEvent('beforedownload', array(
            &$this,
            &$params,
            &$file
        ));

        if(\go\core\model\Module::isInstalled('community', 'history')) {
            Module::logActiveRecord($file, 'download');
        }

        //Supports range download
        $coreFsFile = new \go\core\fs\File($file->fsFile->path());

        // prevent html to render on same domain having access to all global JS stuff
        if($coreFsFile->getContentType() == 'text/html') {
            $inline = false;
        }

        $coreFsFile->output(true, !array_key_exists('cache', $params) || !empty($params['cache']), [], $inline);

    }catch(NotFound $e) {
        Response::get()->setStatus(404);

        echo $e->getMessage();

    }catch (AccessDenied $e) {
        Response::get()->setStatus(403);

        echo $e->getMessage();

    }catch(\Throwable $e) {
        Response::get()->setStatus(500);

        echo $e->getMessage();
    }
}
/**
 * @param $params
 * @throws AccessDenied
 * @throws \go\core\exception\NotFound
 */
public function actionConvert($params)
{
    $fileId = !empty($params['id']) ? $params['id'] : 0;
    $format = !empty($params['format']) ? $params['format'] : 'pdf';

    //check if file exists
    $fileRecord = \GO\Files\Model\File::model()->findByPk($fileId);
    if (!$fileRecord) {
        throw new \go\core\exception\NotFound();
    }

    //check user permissions
    if (!\GO::user() || !$fileRecord->checkPermissionLevel(\GO\Base\Model\Acl::READ_PERMISSION)) {
        throw new AccessDenied();
    }

    $nameWithoutExtension = $fileRecord->fsFile->nameWithoutExtension();
    $outputFileName = $nameWithoutExtension . '.' . $format;

    //create temporary file
    $tmpFile = \GO\Base\Fs\File::tempFile();

    //convert file -> put output to temporary
    $fileRecord->convertTo($tmpFile, $format);

    $outputFileRecord = $fileRecord->folder->addFilesystemFile($tmpFile, true, $outputFileName);
    if (!$outputFileRecord) {
        throw new Exception('File move error from: '. $tmpFile->path() . ' to '. $fileRecord->folder->getFullPath());
    }

    $response['file'] = $outputFileRecord->getAttributes();
    $response['success'] = true;

    return $response;
}
/**
 * @param $params
 * @throws AccessDenied
 * @throws \go\core\exception\NotFound
 */
public function actionConvertAndDownload($params)
{
    $fileId = !empty($params['id']) ? $params['id'] : 0;
    $format = !empty($params['format']) ? $params['format'] : 'pdf';

    //check if file exists
    $fileRecord = \GO\Files\Model\File::model()->findByPk($fileId);
    if (!$fileRecord) {
        throw new \go\core\exception\NotFound();
    }

    //check user permissions
    if (!\GO::user() || !$fileRecord->checkPermissionLevel(\GO\Base\Model\Acl::READ_PERMISSION)) {
        throw new AccessDenied();
    }

    //create temporary file
    $tmpFile = \GO\Base\Fs\File::tempFile();

    //convert file -> put output to temporary
    $fileRecord->convertTo($tmpFile, $format);

    //get pdf file name
    $nameWithoutExtension = $fileRecord->fsFile->nameWithoutExtension();
    $outputFileName = $nameWithoutExtension . '.' . $format;

    //override previous headers because tempoary
    $extraHeaders = [
        'Content-Disposition' => 'inline; filename="' . $outputFileName . '"',
    ];

    //download
    \GO\Base\Util\Http::outputDownloadHeaders($tmpFile, true, !empty($params['cache']), $extraHeaders);
    $tmpFile->output();
}

