protected function actionOpen($params) {
    if(!empty($params['path'])) {
        $file = \GO\Files\Model\File::model()->findByPath($params['path']);
    } else
    {
        $file = \GO\Files\Model\File::model()->findByPath($params['id']);
    }

    if(!$file){
        throw new \Exception("File not found");
    }

    $response = [
