 */
protected function actionRecalculateDiskUsage($id=false) {

    \GO::session()->closeWriting();

    $users = array();
    if(!empty($id)) {
        $user = \GO\Base\Model\User::model()->findByPk($id);
        if(!empty($user)) {
            $users[] = $user;
