package chart

import (
	"testing"
)

func TestValidateDependency(t *testing.T) {
	dep := &Dependency{
		Name: "example",
	}
	for value, shouldFail := range map[string]bool{
		"abcdefghijklmenopQRSTUVWXYZ-0123456780_": false,
		"-okay":      false,
		"_okay":      false,
		"- bad":      true,
		" bad":       true,
		"bad\nvalue": true,
		"bad ":       true,
		"bad$":       true,
	} {
		dep.Alias = value
		res := dep.Validate()
		if res != nil && !shouldFail {
			t.Errorf("Failed on case %q", dep.Alias)
		} else if res == nil && shouldFail {
			t.Errorf("Expected failure for %q", dep.Alias)
		}
	}
}
func getOutDir(basePath, name string) string {
	outdir := filepath.Join(basePath, name)
	return outdir
}
func saveValuesYAML(out *tar.Writer, c *chart.Chart, base string) error {
	for _, f := range c.Raw {
		if f.Name == ValuesfileName {
			return writeToTar(out, filepath.Join(base, ValuesfileName), f.Data)
		}
	}
	return nil
}
func saveFiles(out *tar.Writer, c *chart.Chart, base string) error {
	for _, f := range c.Files {
		n := filepath.Join(base, f.Name)
		if err := writeToTar(out, n, f.Data); err != nil {
			return err
		}
	}
	return nil
}
