    }
@Override
    public void kill(@NotNull Throwable throwable) {
        killed = throwable;
    }
@Override
    public void moveToStart() {
        raiseIfKilled();
        reset();
        watermark = 0;
        fileInputsIterator = fileInputs.iterator();
    }
@Override
    public boolean moveNext() {
        raiseIfKilled();
        try {
            if (currentReader != null) {
                String line;
                try {
                    line = getLine(currentReader);
                } catch (SocketException | SocketTimeoutException e) {
                    if (backOffPolicy.hasNext()) {
                        return false;
                    }
                    throw e;
                }
                if (line == null) {
                    closeReader();
                    return moveNext();
                }
                cursor.line = line;
                cursor.failure = null;
                return true;
            } else if (currentInputUriIterator != null && currentInputUriIterator.hasNext()) {
                advanceToNextUri(currentInput);
                return moveNext();
            } else if (fileInputsIterator != null && fileInputsIterator.hasNext()) {
                advanceToNextFileInput();
                return moveNext();
            } else {
                reset();
                return false;
            }
        } catch (IOException e) {
            cursor.failure = e;
            closeReader();
