var _ io.ReadCloser = (*lazyBoundedReadCloser)(nil)
var _ io.ReaderAt = (*lazyBoundedReadCloser)(nil)
var _ io.Seeker = (*lazyBoundedReadCloser)(nil)

// lazyBoundedReadCloser is a "lazy" read closer, allocating a file descriptor for the given path only upon the first Read() call.
// Only part of the file is allowed to be read, starting at a given position.
type lazyBoundedReadCloser struct {
	// path is the path to be opened
	path string
	// file is the active file handle for the given path
	file *os.File
	// reader is the LimitedReader that wraps the open file
	reader *io.SectionReader
	start  int64
	size   int64
}

// NewDeferredPartialReadCloser creates a new NewDeferredPartialReadCloser for the given path.
func newLazyBoundedReadCloser(path string, start, size int64) *lazyBoundedReadCloser {
	return &lazyBoundedReadCloser{
		path:  path,
		start: start,
		size:  size,
	}
}

// Read implements the io.Reader interface for the previously loaded path, opening the file upon the first invocation.
func (d *lazyBoundedReadCloser) Read(b []byte) (int, error) {
	if err := d.openFile(); err != nil {
		return 0, err
	}

	n, err := d.reader.Read(b)
	if err != nil && errors.Is(err, io.EOF) {
		// we've reached the end of the file, force a release of the file descriptor. If the file has already been
		// closed, ignore the error.
		if closeErr := d.file.Close(); !errors.Is(closeErr, os.ErrClosed) {
			return n, closeErr
		}
	}
	return n, err
}

// Close implements the io.Closer interface for the previously loaded path / opened file.
func (d *lazyBoundedReadCloser) Close() error {
	if d.file == nil {
		return nil
	}

	err := d.file.Close()
	if err != nil && errors.Is(err, os.ErrClosed) {
		// ignore the fact that this file has already been closed
		err = nil
	}
	d.file = nil
	d.reader = nil
	return err
}

func (d *lazyBoundedReadCloser) Seek(offset int64, whence int) (int64, error) {
	if err := d.openFile(); err != nil {
		return 0, err
	}

	return d.reader.Seek(offset, whence)
}

func (d *lazyBoundedReadCloser) ReadAt(b []byte, off int64) (n int, err error) {
	if err := d.openFile(); err != nil {
		return 0, err
	}

	n, err = d.reader.ReadAt(b, off)
	if err != nil && errors.Is(err, io.EOF) {
		// we've reached the end of the file, force a release of the file descriptor. If the file has already been
		// closed, ignore the error.
		if closeErr := d.file.Close(); !errors.Is(closeErr, os.ErrClosed) {
			return n, closeErr
		}
	}
	return n, err
}

func (d *lazyBoundedReadCloser) openFile() error {
	if d.reader != nil {
		return nil
	}

	file, err := os.Open(d.path)
	if err != nil {
		return err
	}

	d.file = file
	d.reader = io.NewSectionReader(d.file, d.start, d.size)
	return nil
}
func joinPath_createDictionary(dst, name string, isDir bool) (string, error) {
    target := filepath.Join(dst, name)
    if isDir {
        if _, err := os.Stat(target); err != nil {
            if err := os.MkdirAll(target, 0755); err != nil {
                return "", err
            }
        }
    }
    return target, nil
}
const perFileReadLimit = 2 * GB

var ErrTarStopIteration = fmt.Errorf("halt iterating tar")

// tarFile is a ReadCloser of a tar file on disk.
type tarFile struct {
	io.Reader
	io.Closer
}
// IterateTar is a function that reads across a tar and invokes a visitor function for each entry discovered. The iterator
// stops when there are no more entries to read, if there is an error in the underlying reader or visitor function,
// or if the visitor function returns a ErrTarStopIteration sentinel error.
func IterateTar(reader io.Reader, visitor TarFileVisitor) error {
	tarReader := tar.NewReader(reader)
	var sequence int64 = -1
	for {
		sequence++

		hdr, err := tarReader.Next()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return err
		}
		if hdr == nil {
			continue
		}

		if err := visitor(TarFileEntry{
			Sequence: sequence,
			Header:   *hdr,
			Reader:   tarReader,
		}); err != nil {
			if errors.Is(err, ErrTarStopIteration) {
				return nil
			}
			return fmt.Errorf("failed to visit tar entry=%q : %w", hdr.Name, err)
		}
	}
	return nil
}
// ReaderFromTar returns a io.ReadCloser for the Path within a tar file.
func ReaderFromTar(reader io.ReadCloser, tarPath string) (io.ReadCloser, error) {
	var result io.ReadCloser

	visitor := func(entry TarFileEntry) error {
		if entry.Header.Name == tarPath {
			result = &tarFile{
				Reader: entry.Reader,
				Closer: reader,
			}
			return ErrTarStopIteration
		}
		return nil
	}
	if err := IterateTar(reader, visitor); err != nil {
		return nil, err
	}

	if result == nil {
		return nil, &ErrFileNotFound{tarPath}
	}

	return result, nil
}
// MetadataFromTar returns the tar metadata from the header info.
func MetadataFromTar(reader io.ReadCloser, tarPath string) (Metadata, error) {
	var metadata *Metadata
	visitor := func(entry TarFileEntry) error {
		if entry.Header.Name == tarPath {
			var content io.Reader
			if entry.Header.Size > 0 {
				content = reader
			}
			m := NewMetadata(entry.Header, content)
			metadata = &m
			return ErrTarStopIteration
		}
		return nil
	}
	if err := IterateTar(reader, visitor); err != nil {
		return Metadata{}, err
	}
	if metadata == nil {
		return Metadata{}, &ErrFileNotFound{tarPath}
	}
	return *metadata, nil
}
