	}
	tests := []testCase{
		{
			name: "empty set",
			s:    NewIDSet(),
			want: 0,
		},
		{
			name: "non-empty set",
			s:    NewIDSet(1, 2, 3),
			want: 3,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.s.Size(); got != tt.want {
				t.Errorf("Size() = %v, want %v", got, tt.want)
			}
		})
	}
}

