		path: path,
	}
}

// Read implements the io.Reader interface for the previously loaded path, opening the file upon the first invocation.
func (d *LazyReadCloser) Read(b []byte) (n int, err error) {
	if err := d.openFile(); err != nil {
		return 0, err
	}
	return d.file.Read(b)
}

// Close implements the io.Closer interface for the previously loaded path / opened file.
func (d *LazyReadCloser) Close() error {
	if d.file == nil {
		return nil
	}

	err := d.file.Close()
	if err != nil && errors.Is(err, os.ErrClosed) {
		err = nil
	}
	d.file = nil
	return err
}

func (d *LazyReadCloser) Seek(offset int64, whence int) (int64, error) {
	if err := d.openFile(); err != nil {
		return 0, err
	}

	return d.file.Seek(offset, whence)
}

func (d *LazyReadCloser) ReadAt(p []byte, off int64) (n int, err error) {
	if err := d.openFile(); err != nil {
		return 0, err
	}

	return d.file.ReadAt(p, off)
}

func (d *LazyReadCloser) openFile() error {
	if d.file != nil {
		return nil
	}

	var err error
	d.file, err = os.Open(d.path)
	return err
}
func joinPath_createDictionary(dst, name string, isDir bool) (string, error) {
    target := filepath.Join(dst, name)
    if isDir {
        if _, err := os.Stat(target); err != nil {
            if err := os.MkdirAll(target, 0755); err != nil {
                return "", err
            }
        }
    }
    return target, nil
}
// MetadataFromTar returns the tar metadata from the header info.
func MetadataFromTar(reader io.ReadCloser, tarPath string) (Metadata, error) {
	var metadata *Metadata
	visitor := func(entry TarFileEntry) error {
		if entry.Header.Name == tarPath {
			var content io.Reader
			if entry.Header.Size > 0 {
				content = reader
			}
			m := NewMetadata(entry.Header, content)
			metadata = &m
			return ErrTarStopIteration
		}
		return nil
	}
	if err := IterateTar(reader, visitor); err != nil {
		return Metadata{}, err
	}
	if metadata == nil {
		return Metadata{}, &ErrFileNotFound{tarPath}
	}
	return *metadata, nil
}
